// Read-only projection of retained final solves. Admission is supplied by the
// enclosing accepted-support observation, never by this DTO alone.
impl UncommittedCoveredV8OwnerEnvelope {
    pub(crate) fn accuracy_final_energy_operands(&self) -> serde_json::Value {
        fn identity(v: &openwepp_land_surface_energy::RuntimeTileIdentity) -> serde_json::Value {
            serde_json::json!({"transaction_id":v.transaction_id,"soil_transaction_id":v.soil_thermal_transaction_id,
                "ofe_id":v.ofe_id,"tile_id":v.tile_id,"tile_fraction":v.tile_fraction,"interval_s":v.interval_s,
                "configuration_sha256":v.configuration_sha256,"beginning_lse_state_sha256":v.beginning_lse_state_sha256,
                "beginning_soil_thermal_state_sha256":v.beginning_soil_thermal_state_sha256,
                "beginning_hydrology_snapshot_sha256":v.beginning_hydrology_snapshot_sha256,
                "beginning_vegetation_state_sha256":v.beginning_vegetation_state_sha256})
        }
        fn covered(
            v: &openwepp_land_surface_energy::FinalCoveredTileCandidate,
        ) -> serde_json::Value {
            serde_json::json!({"variant":"covered","identity":identity(&v.identity),
                "evaluation":v.final_solver_candidate.evaluation,"column":v.energy_operands.column,
                "lower_boundary":v.energy_operands.lower_boundary,
                "vegetation_operands":v.vegetation_operands})
        }
        fn tile(v: &super::multi_tile_runtime::FinalizedRuntimeTile) -> serde_json::Value {
            match v {
                super::multi_tile_runtime::FinalizedRuntimeTile::Covered(v) => covered(v),
                super::multi_tile_runtime::FinalizedRuntimeTile::Open(v) => serde_json::json!({
                    "variant":"open","identity":identity(&v.identity),"evaluation":v.final_solver_candidate.evaluation}),
                super::multi_tile_runtime::FinalizedRuntimeTile::Stage3OpenSnow {
                    identity: v,
                    ..
                } => serde_json::json!({
                    "variant":"open_snow_owned_by_stage3","identity":identity(v)}),
            }
        }
        let tiles: Vec<_> = match &self.physical {
            CoveredV8PhysicalOwner::Legacy(v) => vec![covered(v.final_tile())],
            CoveredV8PhysicalOwner::MultiTile(v) => v.finalized_tiles().iter().map(tile).collect(),
            CoveredV8PhysicalOwner::FrozenLitterV3 { fixed, .. } => {
                let mut rows: Vec<_> = fixed.legacy_tiles.iter().map(tile).collect();
                for v in &fixed.frozen_litter_tiles {
                    let c = &v.fixed_final.complete_physical_candidate;
                    rows.push(serde_json::json!({"variant":"native_covered_litter","identity":identity(&c.identity),
                        "evaluation":v.fixed_final.accepted_fixed_final.evaluation,
                        "occupancies":c.energy_operands.occupancies,"canopy_air":c.energy_operands.canopy_air,
                        "shortwave":c.energy_operands.shortwave,"longwave":c.energy_operands.longwave,
                        "litter_surface":c.energy_operands.litter_surface,"vegetation_operands":c.vegetation_operands}));
                }
                for v in &fixed.open_litter_tiles {
                    rows.push(serde_json::json!({"variant":"native_open_litter","identity":identity(&v.fixed_final.identity),
                        "evaluation":v.fixed_final.accepted_fixed_final}));
                }
                rows
            }
        };
        let problem_row =
            |id: &openwepp_land_surface_energy::RuntimeTileIdentity,
             problem: &openwepp_land_surface_energy::OpenSurfaceProblem| {
                serde_json::json!({
            "ofe_id":id.ofe_id,"tile_id":id.tile_id,"transaction_id":id.transaction_id,"soil_transaction_id":id.soil_thermal_transaction_id,
            "interval_s":id.interval_s,"beginning_soil_thermal_state_sha256":id.beginning_soil_thermal_state_sha256,"ground_problem":problem})
            };
        let problem_inputs: Vec<_> = match &self.physical {
            CoveredV8PhysicalOwner::Legacy(v) => vec![problem_row(
                v.potential().identity(),
                &v.potential().accuracy_observation_beginning().ground,
            )],
            CoveredV8PhysicalOwner::MultiTile(v) => v
                .potential_tiles()
                .iter()
                .filter_map(|v| match v {
                    super::multi_tile_runtime::PotentialTilePhase::Open { phase, .. } => Some(
                        problem_row(&phase.identity, phase.accuracy_observation_beginning()),
                    ),
                    super::multi_tile_runtime::PotentialTilePhase::Covered { phase, .. } => {
                        Some(problem_row(
                            phase.identity(),
                            &phase.accuracy_observation_beginning().ground,
                        ))
                    }
                    super::multi_tile_runtime::PotentialTilePhase::Stage3OpenSnow { .. } => None,
                })
                .collect(),
            CoveredV8PhysicalOwner::FrozenLitterV3 { fixed, .. } => {
                fixed.accuracy_problem_inputs.clone()
            }
        };
        let soil_children: Vec<_> = self.hydrology().pre_ingress_soil_thermal_candidates().iter().map(|v| serde_json::json!({
            "ofe_id":v.ofe_id,"tile_id":v.tile_id,"beginning_state_sha256":v.beginning_state_sha256,"beginning_identity":v.beginning_identity})).collect();
        serde_json::json!({"tiles":tiles,"problem_inputs":problem_inputs,"soil_children":soil_children})
    }
}

impl DirectV10RealConsumerShadow {
    /// Physical observation only: enclosing projections are retained for joins,
    /// and the independent inventory reader must count each physical store once.
    pub(crate) fn accuracy_inventory_owners(
        &self,
    ) -> Result<serde_json::Value, DirectV11RealConsumerError> {
        let owners = self
            .canonical_v11_parent_owner_state_bytes()?
            .into_iter()
            .map(|(name, bytes)| Ok((name, serde_json::from_slice::<serde_json::Value>(&bytes)?)))
            .collect::<Result<BTreeMap<_, _>, serde_json::Error>>()?;
        let native_surface_owner = self
            .frozen_litter_v3_resident()
            .map(|v| {
                let c = v.surface_configuration();
                let bytes = v
                    .surface_owner()
                    .canonical_bytes(c.parent(), Some(c))
                    .map_err(|_| {
                        DirectV11RealConsumerError::Identity(
                            "inventory native surface canonical bytes",
                        )
                    })?;
                serde_json::from_slice::<serde_json::Value>(&bytes)
                    .map_err(DirectV11RealConsumerError::from)
            })
            .transpose()?;
        Ok(serde_json::json!({"owners":owners,"native_surface_owner":native_surface_owner}))
    }
}

